package com.oms.supplychain.service.wms;

import com.oms.common.api.SharedCarrierClient;
import com.ruoyi.common.core.constant.SecurityConstants;
import com.ruoyi.common.core.domain.R;
import org.springframework.stereotype.Service;
import org.springframework.scheduling.annotation.Scheduled;
import javax.annotation.Resource;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Carrier lookup is independent of physical inventory facts. Raw facts use a durable local outbox. */
@Service
public class WmsCarrierBridge {
    @Resource private WmsStore db;
    @Resource private com.oms.common.carrier.CarrierBackground background;
    @Resource private SharedCarrierClient carriers;
    public Map<String,Object> context(String c,String store,String purpose){Map<String,Object> w=db.one("SELECT v.connection_id,v.outbound_mode,v.inbound_mode,c.provider,o.owner_code,w.real_store_code FROM wms_simulation_store_info v JOIN owner_warehouse r ON r.company_key=v.company_key AND r.id=v.owner_warehouse_id JOIN owner_info o ON o.company_key=r.company_key AND o.id=r.owner_id JOIN wms_real_store_info w ON w.company_key=r.company_key AND w.id=r.real_store_id LEFT JOIN wms_connection c ON c.company_code=v.company_key AND c.id=v.connection_id WHERE v.company_key=? AND v.wms_simulation_code=?",c,store);boolean virtual=id(w.get(purpose.contains("OUTBOUND")?"outbound_mode":"inbound_mode"))==2;require(virtual||w.get("connection_id")!=null,"该仓尚未配置WMS连接，不能确认目标快递编码");return map("virtual",virtual,"system_type","WMS","provider",w.get("provider"),"purpose",purpose,"connection_id",String.valueOf(w.get("connection_id")),"owner_code",w.get("owner_code"),"real_store_code",w.get("real_store_code"));}
    public Map<String,Object> options(String c,long purchase,String flow,String province,String keyword){Map<String,Object> p=db.one("SELECT wms_simulation_code FROM po_info WHERE company_key=? AND id=?",c,purchase);Map<String,Object> ctx=context(c,text(p.get("wms_simulation_code")),"INBOUND".equals(flow)?"WMS_RETURN_CREATE":"WMS_OUTBOUND_CREATE");ctx.put("province",province(province));ctx.put("keyword",keyword);if(Boolean.TRUE.equals(ctx.get("virtual")))return virtualOptions(c,ctx,keyword);return data(carriers.options(c,ctx,SecurityConstants.INNER));}
    public Map<String,Object> choose(String c,String store,long standard,String province,String flow){require(standard>0,"请选择公共标准快递，不能以手填外部编码代替");Map<String,Object> ctx=context(c,store,"INBOUND".equals(flow)?"WMS_RETURN_CREATE":"WMS_OUTBOUND_CREATE");ctx.put("direction","OUT");ctx.put("standard_id",standard);ctx.put("province",province(province));if(Boolean.TRUE.equals(ctx.get("virtual")))return virtualChoice(c,standard,ctx);Map<String,Object> r=data(carriers.convert(c,ctx,SecurityConstants.INNER));require(Boolean.TRUE.equals(r.get("available")),text(r.get("message")));return r;}
    public Map<String,Object> freeze(String c,String request,Map<String,Object> head,String flow){Map<String,Object> ctx=context(c,text(head.get("store_code")),"INBOUND".equals(flow)?"WMS_RETURN_CREATE":"WMS_OUTBOUND_CREATE");ctx.put("direction","OUT");ctx.put("standard_id",head.get("standard_id"));if(Boolean.TRUE.equals(ctx.get("virtual")))return virtualChoice(c,id(head.get("standard_id")),ctx);Map<String,Object> expected=obj(head.get("carrier_route"));if(expected.get("connection_id")!=null)require(text(expected.get("connection_id")).equals(text(ctx.get("connection_id"))),"仓库连接在转换前变化，请刷新核对原下发目标");Map<String,Object> receiver=obj(head.get("receiver_json"));ctx.put("province",province(text(receiver.get("province"))));Map<String,Object> r=data(carriers.freeze(c,request,ctx,SecurityConstants.INNER));require(Boolean.TRUE.equals(r.get("available")),text(r.get("message")));return r;}
    @SuppressWarnings("unchecked") private Map<String,Object> virtualOptions(String c,Map<String,Object> ctx,String keyword){Map<String,Object> page=data(carriers.standards(c,keyword,SecurityConstants.INNER));for(Map<String,Object> row:(List<Map<String,Object>>)page.get("rows")){row.put("available",id(row.get("enabled"))==1);row.put("reason",id(row.get("enabled"))==1?"虚拟执行，无需WMS编码":text(row.get("disabled_reason")));row.put("conversion",map("virtual",true,"external_code","","state",id(row.get("enabled"))==1?"RESOLVED":"DISABLED"));}page.put("context",ctx);return page;}
    private Map<String,Object> virtualChoice(String c,long standard,Map<String,Object> ctx){require(standard>0,"请选择标准快递身份");Map<String,Object> s=data(carriers.standard(c,standard,SecurityConstants.INNER));require(id(s.get("enabled"))==1,"标准快递已停用");return map("available",true,"state","RESOLVED","virtual",true,"standard_id",s.get("id"),"standard_code",s.get("standard_code"),"standard_name",s.get("standard_name"),"external_code","","context",ctx,"message","虚拟执行，无需WMS编码");}
    /** Province normalization only affects service areas, never external carrier codes. */
    private String province(String p){for(String suffix:Arrays.asList("维吾尔自治区","壮族自治区","回族自治区","特别行政区","自治区","省","市"))if(p.endsWith(suffix)){return p.substring(0,p.length()-suffix.length());}return p;}
    @SuppressWarnings("unchecked") private Map<String,Object> obj(Object value){if(value==null)return Collections.emptyMap();try{return value instanceof Map?(Map<String,Object>)value:db.json.readValue(text(value),Map.class);}catch(Exception e){throw new IllegalArgumentException("快递业务上下文无法解析");}}
    private Map<String,Object> data(R<Map<String,Object>> r){require(r!=null&&R.isSuccess(r),"公共快递服务暂不可用，请重试查询");return r.getData();}
    public void fact(String c,String type,long business,String sn,String fact,Map<String,Object> context){Map<String,Object> body=map("business_type",type,"business_id",business,"business_sn",sn,"fact_id",fact,"blocked_action","RESOLVE_ACTUAL","context",context);String hash=QimenProtocol.hash("SHA-256",db.encode(Arrays.asList(type,business,fact,context.get("purpose"),context.get("external_code"))));db.jdbc.update("INSERT IGNORE INTO wms_carrier_fact(company_code,fact_hash,payload_json,business_type,business_id,fact_id) VALUES (?,?,?,?,?,?)",c,hash,db.encode(body),type,business,fact);}
    /** New inbound execution: identify the original channel code, then convert to this exact WMS target. */
    public Map<String,Object> inbound(String c,Map<String,Object> task,Map<String,Object> connection){
        task=new LinkedHashMap<>(task);Map<String,Object> original=obj(task.get("input_json"));for(String key:Arrays.asList("channel_id","return_carrier","standard_id","carrier_source_provider","carrier_source_connection"))if(task.get(key)==null&&original.get(key)!=null)task.put(key,original.get(key));
        String request="RETURN_"+required(task,"return_sn",100);String binding=QimenProtocol.hash("SHA-256",db.encode(Arrays.asList(connection.get("id"),connection.get("provider"),task.get("owner_code"),task.get("real_store_code"),task.get("return_carrier"),task.get("channel_id"),task.get("standard_id"))));List<Map<String,Object>> old=db.jdbc.queryForList("SELECT snapshot_json,context_hash FROM wms_carrier_execution WHERE company_code=? AND request_id=?",c,request);
        if(!old.isEmpty()){require(binding.equals(text(old.get(0).get("context_hash"))),"原快递请求上下文已冻结，禁止改变来源或仓库重试");return obj(old.get(0).get("snapshot_json"));}
        long standard=task.get("standard_id")==null?0:id(task.get("standard_id"));String raw=text(task.get("return_carrier"));
        if(standard==0){Map<String,Object> source=map("system_type","CHANNEL","provider",task.getOrDefault("carrier_source_provider","TMALL"),"purpose","CHANNEL_RETURN_IDENTIFY","shop_id",text(task.get("channel_id")),"connection_id",task.getOrDefault("carrier_source_connection",""),"direction","IN","external_code",raw);Map<String,Object> body=map("business_type",text(task.get("business_type")).startsWith("EXCHANGE")?"EXCHANGE":"REFUND","business_id",task.getOrDefault("exchange_id",task.getOrDefault("refund_id",0)),"business_sn",task.getOrDefault("business_sn",task.get("return_sn")),"fact_id",task.get("return_sn"),"blocked_action","INBOUND_DISPATCH","context",source);Map<String,Object> identified=data(carriers.fact(c,body,SecurityConstants.INNER));require(Boolean.TRUE.equals(identified.get("available")),"原始寄回快递尚未识别："+text(identified.get("message"))+"；物流事实已保留，请处理快递关联待办");standard=id(identified.get("standard_id"));}
        Map<String,Object> target=map("system_type","WMS","provider",connection.get("provider"),"purpose","WMS_RETURN_CREATE","connection_id",String.valueOf(connection.get("id")),"owner_code",task.get("owner_code"),"real_store_code",task.get("real_store_code"),"direction","OUT","standard_id",standard);
        Map<String,Object> result=data(carriers.freeze(c,request,target,SecurityConstants.INNER));if(!Boolean.TRUE.equals(result.get("available"))){Map<String,Object> body=map("business_type","REFUND","business_id",task.getOrDefault("refund_id",0),"business_sn",task.getOrDefault("business_sn",task.get("return_sn")),"fact_id",task.get("return_sn"),"blocked_action","INBOUND_DISPATCH","context",target);carriers.fact(c,body,SecurityConstants.INNER);throw new IllegalArgumentException("退回入库快递未就绪："+text(result.get("message")));}
        db.jdbc.update("INSERT IGNORE INTO wms_carrier_execution(company_code,request_id,context_hash,snapshot_json) VALUES (?,?,?,?)",c,request,binding,db.encode(result));Map<String,Object> accepted=db.one("SELECT snapshot_json,context_hash FROM wms_carrier_execution WHERE company_code=? AND request_id=?",c,request);require(binding.equals(text(accepted.get("context_hash"))),"原入库快递执行已冻结，禁止并发改变来源或仓库连接");return obj(accepted.get("snapshot_json"));
    }
    @Scheduled(fixedDelay=15000) public void queueResolution(){background.each("FACT",this::resolveFacts);}
    public void resolveFacts(String company){for(Map<String,Object> f:db.jdbc.queryForList("SELECT * FROM wms_carrier_fact WHERE company_code=? AND state IN('PENDING','RETRY','WAIT_CONFIG') AND next_attempt<=NOW() ORDER BY next_attempt,id LIMIT 3",company)){
        if(db.jdbc.update("UPDATE wms_carrier_fact SET next_attempt=DATE_ADD(NOW(),INTERVAL 5 MINUTE),attempts=attempts+1 WHERE company_code=? AND id=? AND next_attempt<=NOW()",company,f.get("id"))==1)resolveRow(company,f);
    }}
    public Map<String,Object> retryFact(String company,String type,long business,String identity,String raw){List<Map<String,Object>> facts=db.jdbc.queryForList("SELECT * FROM wms_carrier_fact WHERE company_code=? AND business_type=? AND business_id=? AND fact_id=? AND JSON_UNQUOTE(JSON_EXTRACT(payload_json,'$.context.external_code'))=? ORDER BY id DESC LIMIT 2",company,type,business,identity,raw);require(facts.size()==1,"原物流事实不存在或存在多个版本，请在原单核对");Map<String,Object> fact=facts.get(0);if("RESOLVED".equals(fact.get("state")))return obj(fact.get("resolution_json"));db.jdbc.update("UPDATE wms_carrier_fact SET attempts=attempts+1,next_attempt=DATE_ADD(NOW(),INTERVAL 5 MINUTE) WHERE company_code=? AND id=?",company,fact.get("id"));return resolveRow(company,fact);}
    private Map<String,Object> resolveRow(String company,Map<String,Object> f){
        try{Map<String,Object> incoming=data(carriers.fact(company,obj(f.get("payload_json")),SecurityConstants.INNER));return db.tx().execute(status->{Map<String,Object> result=incoming;db.jdbc.update("UPDATE wms_carrier_fact SET state=?,resolution_json=?,last_error=? WHERE company_code=? AND id=? AND state<>'RESOLVED'",Boolean.TRUE.equals(result.get("available"))?"RESOLVED":"WAIT_CONFIG",db.encode(result),text(result.get("message")),company,f.get("id"));Map<String,Object> accepted=db.one("SELECT state,resolution_json FROM wms_carrier_fact WHERE company_code=? AND id=?",company,f.get("id"));result=obj(accepted.get("resolution_json"));
            if("PURCHASE_RETURN".equals(f.get("business_type"))&&text(f.get("fact_id")).matches("PARCEL_[0-9]+")){long parcel=Long.parseLong(text(f.get("fact_id")).substring(7));db.jdbc.update("UPDATE purchase_return_parcel SET standard_id=?,carrier_resolution_state=?,carrier_resolution_json=? WHERE company_code=? AND return_id=? AND id=? AND carrier_resolution_state<>'RESOLVED'",Boolean.TRUE.equals(result.get("available"))?result.get("standard_id"):null,result.get("state"),db.encode(result),company,f.get("business_id"),parcel);}
            return result;});
        }catch(RuntimeException e){db.jdbc.update("UPDATE wms_carrier_fact SET state='RETRY',last_error='公共快递服务未确认，原始物流和库存事实已保留' WHERE company_code=? AND id=? AND state<>'RESOLVED'",company,f.get("id"));return map("available",false,"state","RETRY","message","公共快递服务未确认，请稍后重试；原始物流和库存事实保留");}
    }
}
